catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  if (isLoading || newValue == '') {
    return;
  }

  g_form.setDisplay('geo', false);
  g_form.setDisplay('country', false);
  g_form.setDisplay('company', false);
  g_form.setDisplay('variable_1', false);
  g_form.setDisplay('variable_2', false);
  g_form.setDisplay('variable_3', false);
  g_form.setDisplay('variable_4', false);
  g_form.setDisplay('variable_5', false);
  g_form.setDisplay('variable_6', false);
  g_form.setDisplay('requested_by', false);
  g_form.setDisplay('altemate_buyer', false);
  g_form.setDisplay('first_payment_approver_display', false);

  if (newValue == 1) {
    g_form.setDisplay('geo', true);
    g_form.setDisplay('country', true);
    g_form.setDisplay('company', true);
  }
  if (newValue == 2) {
    g_form.setDisplay('variable_1', true);
    g_form.setDisplay('variable_2', true);
    g_form.setDisplay('variable_3', true);
  }
  else if (newValue == 3) {
    g_form.setDisplay('variable_4', true);
    g_form.setDisplay('variable_5', true);
  }
  else if (newValue == 4) {
    g_form.setDisplay('variable_6', true);
  }
  else if (newValue == 5) {
    g_form.setDisplay('requested_by', true);
    g_form.setDisplay('altemate_buyer', true);
    g_form.setDisplay('first_payment_approver_display', true);
  }
}
